      (v_l_4,v_c_lena,1,'character','Hallo! Wie heißt du?','سلام! اسمت چیست؟',1,NULL,NULL,JSON_ARRAY(),JSON_OBJECT()),(v_l_4,v_c_raha,2,'learner','Hallo! Ich heiße Raha.','سلام! من رها هستم.',1,'Hallo! Ich heiße Raha.',JSON_ARRAY('Hallo! Ich heiße Raha.','Hallo! Ich bin Raha.'),JSON_ARRAY(),JSON_OBJECT()),(v_l_4,v_c_lena,3,'character','Woher kommst du?','اهل کجا هستی؟',1,NULL,NULL,JSON_ARRAY(),JSON_OBJECT()),(v_l_4,v_c_raha,4,'learner','Ich komme aus Iran.','من اهل ایران هستم.',1,'Ich komme aus Iran.',JSON_ARRAY('Ich komme aus Iran.','Ich bin aus Iran.'),JSON_ARRAY(),JSON_OBJECT()),(v_l_4,v_c_lena,5,'character','Wo wohnst du jetzt?','الان کجا زندگی می‌کنی؟',1,NULL,NULL,JSON_ARRAY(),JSON_OBJECT()),(v_l_4,v_c_raha,6,'learner','Ich wohne in Berlin.','من در برلین زندگی می‌کنم.',1,'Ich wohne in Berlin.',JSON_ARRAY('Ich wohne in Berlin.','In Berlin.'),JSON_ARRAY(),JSON_OBJECT()),(v_l_4,v_c_lena,7,'character','Freut mich. Bis später!','از آشنایی خوشحالم. بعدا می‌بینمت!',1,NULL,NULL,JSON_ARRAY(),JSON_OBJECT()),(v_l_4,v_c_raha,8,'learner','Freut mich auch. Tschüss!','من هم از آشنایی خوشحالم. خداحافظ!',1,'Freut mich auch. Tschüss!',JSON_ARRAY('Freut mich auch. Tschüss!','Mich auch. Bis später!'),JSON_ARRAY(),JSON_OBJECT());
    INSERT INTO activities (lesson_id,activity_type,sort_order,prompt,instruction,difficulty,config,metadata) VALUES
      (v_l_4,'listen',1,'Hallo! Wie heißt du?','گوش کن.',1,CAST('{"mode":"audio_first","input":"none","scored":false}' AS JSON),JSON_OBJECT()),(v_l_4,'reading_comprehension',2,'نام + مبدأ + محل زندگی','نقشه پاسخ را مرور کن.',1,CAST('{"mode":"micro_grammar","explanation_fa":"سه الگو را بازیابی کن: Ich heiße..., Ich komme aus..., Ich wohne in....","input":"none","scored":false}' AS JSON),JSON_OBJECT()),(v_l_4,'speak',3,'نامت را بگو.','از حافظه.',1,CAST('{"mode":"recall_hidden","cue_fa":"نامت را بگو.","accepted":["Ich heiße Raha.","Ich bin Raha."],"input":"speech","scored":true}' AS JSON),JSON_OBJECT()),(v_l_4,'speak',4,'مبدأت را بگو.','از حافظه.',1,CAST('{"mode":"recall_hidden","cue_fa":"بگو اهل ایران هستی.","accepted":["Ich komme aus Iran.","Ich bin aus Iran."],"input":"speech","scored":true}' AS JSON),JSON_OBJECT()),(v_l_4,'speak',5,'محل زندگی را بگو.','از حافظه.',1,CAST('{"mode":"recall_hidden","cue_fa":"بگو در برلین زندگی می‌کنی.","accepted":["Ich wohne in Berlin.","Ich lebe in Berlin."],"input":"speech","scored":true}' AS JSON),JSON_OBJECT()),(v_l_4,'meaning_choice',6,'Ich wohne ___ Berlin.','کامل کن.',1,CAST('{"mode":"sentence_blank","options":["in","aus","woher"],"answer_index":0,"input":"tap_choice","scored":true}' AS JSON),JSON_OBJECT()),(v_l_4,'reading',7,'Woher kommst du? — Ich komme aus Iran. Wo wohnst du? — Ich wohne in Berlin.','متن را بخوان.',1,CAST('{"mode":"reading_input","text":"Woher kommst du? — Ich komme aus Iran. Wo wohnst du? — Ich wohne in Berlin.","input":"none","scored":false}' AS JSON),JSON_OBJECT()),(v_l_4,'reading_comprehension',8,'Wo wohnt Raha?','جواب را پیدا کن.',1,CAST('{"mode":"reading_inference","options":["In Berlin.","Aus Iran.","In Jonas."],"answer_index":0,"input":"tap_choice","scored":true}' AS JSON),JSON_OBJECT()),(v_l_4,'pronunciation',9,'Wo wohnst du?','w آلمانی را تقلید کن.',1,CAST('{"mode":"sound_notice","target":"z_ts_and_w_v","input":"speech","scored":false}' AS JSON),JSON_OBJECT()),(v_l_4,'speak',10,'گفت‌وگوی آشنایی را تمام کن.','مرور Series 001.',1,CAST('{"mode":"scenario_transfer","scenario_fa":"بعد از آشنایی پاسخ مناسب و خداحافظی بگو.","accepted_intents":["Freut mich auch. Tschüss!","Mich auch. Bis später!"],"input":"speech","scored":true}' AS JSON),JSON_OBJECT()),(v_l_4,'speak',11,'خودت را مستقل معرفی کن.','mastery transfer.',1,CAST('{"mode":"scenario_transfer","scenario_fa":"نام، مبدأ و محل زندگی را بدون راهنما بگو.","accepted_intents":["Hallo! Ich heiße Raha. Ich komme aus Iran. Ich wohne in Berlin.","Hallo! Ich bin Raha. Ich bin aus Iran und wohne in Berlin."],"input":"speech","scored":true}' AS JSON),JSON_OBJECT()),(v_l_4,'speak',12,'دو پرسش بپرس.','mastery transfer.',1,CAST('{"mode":"scenario_transfer","scenario_fa":"از فرد تازه بپرس اهل کجاست و کجا زندگی می‌کند.","accepted_intents":["Woher kommst du? Wo wohnst du?","Und woher kommst du? Wo wohnst du?"],"input":"speech","scored":true}' AS JSON),JSON_OBJECT());
